```cpp
    void InspectorHost::InvalidateSource(InspectorSource& source)
    {
        // Prune every history entry naming it, keeping the cursor on the
        // entry it pointed at (or clamped when that entry went too).
        const HistoryEntry* at = m_history.empty() ? nullptr : &m_history[m_cursor];
        const bool cursorSurvives = at && at->source != &source;
        InspectorSource* atSource = at ? at->source : nullptr;
        const std::string atKey = at ? at->key : std::string{};
        std::erase_if(m_history, [&](const HistoryEntry& e) { return e.source == &source; });
        if (m_history.empty()) m_cursor = 0;
        else if (cursorSurvives)
        {
            for (std::size_t i = 0; i < m_history.size(); ++i)
                if (m_history[i].source == atSource && m_history[i].key == atKey) { m_cursor = i; break; }
            m_cursor = std::min(m_cursor, m_history.size() - 1);
        }
        else m_cursor = std::min(m_cursor, m_history.size() - 1);
        for (Instance& inst : m_instances)
            if (inst.pinned && inst.pinnedSource == &source)
                inst.pinnedSource = nullptr;      // sourceClosed stays false: "Pinned selection is gone"
    }

    void InspectorHost::RemoveSource(InspectorSource& source)
    {
        if (&source == m_fallback) return;
        InvalidateSource(source);
        std::erase(m_sources, &source);
        if (m_current == &source) m_current = m_fallback;
        for (Instance& inst : m_instances)
            if (inst.pinned && inst.pinnedSource == nullptr && inst.pinnedName == source.SourceName() && !inst.sourceClosed)
                inst.sourceClosed = true;
    }
```
(Simpler equivalent allowed: have InvalidateSource take a `bool closed` and set `inst.sourceClosed = closed` in the pin loop; RemoveSource passes true, the public overload passes false. The cursor re-find uses the surviving entry's own source, not m_current, so it is correct whether or not Current() changed.)

