Task 1 Step 4 (PropertyGrid.cpp): replace the bodies of `PropertyGrid::IntRow` and `PropertyGrid::FloatRow` with:

```cpp
    namespace
    {
        // Shared drag/commit path for both numeric rows (UE routes every numeric
        // property through one SSpinBox). The row's draft owns the in-flight
        // number; the caller's reference is written through every frame so a
        // caller that passes persistent storage sees the value follow the drag
        // (UE's InteractiveChange push), and a caller that rebuilds its local
        // from an unchanged document every frame still accumulates correctly.
        // Returns true exactly once per gesture, and only when the released
        // value differs from the value at activation (UE's OrgValue != NewValue).
        template <typename T, typename DrawFn>
        bool NumericRow(PropertyGridState& state, T& value, DrawFn&& draw)
        {
            const unsigned int key = ImGui::GetID("##value");
            auto [it, inserted] = state.numericDrafts.try_emplace(key, PropertyGridState::NumericDraft{});
            PropertyGridState::NumericDraft& draft = it->second;
            // Re-seed from live data whenever THIS widget was not active on its
            // last draw (same gate as TextRow: the draft's own flag, never
            // IsAnyItemActive()). While active, the external value is never
            // consulted: pages only mutate the document on commit, so there is
            // no external change to detect mid-gesture.
            if (!draft.active) { draft.value = static_cast<double>(value); draft.seed = draft.value; }
            T local = static_cast<T>(draft.value);
            draw(local);                       // DragInt / DragFloat on the row-owned copy
            draft.value = static_cast<double>(local);
            value = local;                     // write-through: the caller's reference follows the gesture
            draft.active = ImGui::IsItemActive();
            bool committed = false;
            if (ImGui::IsItemDeactivatedAfterEdit())
                committed = draft.value != draft.seed;
            if (ImGui::IsItemDeactivated())
                state.numericDrafts.erase(it);   // gesture over (edited or not): drop the draft
            return committed;
        }
    }

    bool PropertyGrid::IntRow(const char* label, int& value)
    {
        (void)FieldLabelCell(label, false);
        ImGui::PushID(label);
        const bool committed = NumericRow(m_state, value, [](int& v) { ImGui::DragInt("##value", &v, 1.0f); });
        Probe(label);
        ImGui::PopID();
        return committed;
    }

    bool PropertyGrid::FloatRow(const char* label, float& value, float speed)
    {
        (void)FieldLabelCell(label, false);
        ImGui::PushID(label);
        const bool committed = NumericRow(m_state, value, [speed](float& v) { ImGui::DragFloat("##value", &v, speed, 0.0f, 0.0f, "%.2f"); });
        Probe(label);
        ImGui::PopID();
        return committed;
    }
```

(IntRow moves from `InputInt` to `DragInt`, the same widget `EditorWidgets.cpp:389 RangedDragInt` already uses, so both numeric rows share the one draft/commit path; `Probe(label)` must stay immediately after the widget call inside NumericRow's caller as written, since it reads the last item's rect.) In the PropertyGrid.hpp header comment that says "Drag/typing in flight commits nothing", append: "the row, not the page, owns the in-flight number; the caller's reference follows the gesture and the commit is reported once, on release, only if the number changed."

