    // Shared tail of IntRow/FloatRow, run right after the value widget while it
    // is still LastItemData (ClearActiveID then stamps ElapseFrame == this
    // frame, so next frame's IsItemDeactivatedAfterEdit stays false).
    template <typename T>
    bool PropertyGrid::NumericCommit(T& value)
    {
        const unsigned int id = ImGui::GetItemID();
        auto& seed = m_state.numericSeed;
        if (ImGui::IsItemActivated()) seed = { id, static_cast<double>(value) };
        // Escape mid-DRAG (button held; text mode has no button down and
        // InputText reverts on its own): restore the seed, end the gesture.
        if (ImGui::IsItemActive() && seed.id == id && ImGui::IsMouseDown(ImGuiMouseButton_Left)
            && ImGui::IsKeyPressed(ImGuiKey_Escape, false))
        {
            value = static_cast<T>(seed.value);
            ImGui::ClearActiveID();
            seed = {};
            return false;
        }
        if (!ImGui::IsItemDeactivatedAfterEdit()) return false;
        const bool changed = seed.id != id || static_cast<double>(value) != seed.value;
        seed = {};
        return changed;   // released ON the seed = no commit (UE: LastSliderCommittedValue != NewValue)
    }
